int open_url(AVFormatContext *s, AVIOContext **pb, const char *url, AVDictionary *opts, AVDictionary *opts2, int *is_http) {
    AVDictionary *temp_opts = NULL;
    int ret;

    // Check the protocol of the URL
    if (av_strstart(url, "http://", NULL) || av_strstart(url, "https://", NULL)) {
        *is_http = 1;
        // Open HTTP URL
        ret = avio_open2(pb, url, AVIO_FLAG_READ, &s->interrupt_callback, &temp_opts);
        if (ret < 0) {
            return ret;
        }
    } else if (av_strstart(url, "file:", NULL)) {
        *is_http = 0;
        // Validate file extension
        const char *ext = strrchr(url, '.');
        if (!ext || (strcasecmp(ext, ".avi") && strcasecmp(ext, ".mp4") && strcasecmp(ext, ".mkv"))) {
            av_log(s, AV_LOG_ERROR, "Unsupported file type: %s\n", ext);
            return AVERROR(EINVAL);
        }

        // Open file URL
        ret = avio_open2(pb, url, AVIO_FLAG_READ, &s->interrupt_callback, &temp_opts);
        if (ret < 0) {
            return ret;
        }
    } else {
        av_log(s, AV_LOG_ERROR, "Unsupported protocol for URL: %s\n", url);
        return AVERROR(EINVAL);
    }

    // Update cookies if needed (for HTTP)
    if (*is_http) {
        AVDictionaryEntry *cookie = av_dict_get(opts, "cookies", NULL, 0);
        if (cookie) {
            av_dict_set(&temp_opts, "cookies", cookie->value, 0);
        }
    }

    // Merge options and cleanup
    av_dict_merge(&temp_opts, opts, AV_DICT_DONT_OVERWRITE);
    av_dict_merge(&temp_opts, opts2, AV_DICT_DONT_OVERWRITE);
    av_dict_free(&temp_opts);

    return 0;
}

